// Share of Voice, como lo define la Estrategia SEO/GEO de BCP: «visibilidad de
// la marca vs la competencia, con un score que pondera el peso de la posición,
// la prominencia y el contexto (positivo/neutral)». Sin dependencias: build.mjs
// lo pega en «Armar fila» y en «Datos del monitor».
//
// Score de cada banco en una respuesta:
//   posición     1 / posición               (1.º = 1, 2.º = 0,5, 3.º = 0,33…)
//   prominencia  sus menciones ÷ menciones de todos los bancos
//   contexto     positivo 1 · neutral 0,75 · negativo 0,25
//   score = (posición + prominencia) / 2 × contexto
// SoV de un banco = su score ÷ la suma de los scores de todos los bancos × 100.

function pesoContexto(sentimiento) {
  const s = Number(sentimiento);
  if (!isFinite(s)) return 0.75;
  return s > 0.2 ? 1 : s < -0.2 ? 0.25 : 0.75;
}

// detalle: [{marca, posicion, menciones, sentimiento}] → {marca: SoV 0-100}
function sovPorMarca(detalle) {
  const lista = (detalle || []).filter(d => d && d.marca);
  const totalMenciones = lista.reduce((n, d) => n + Math.max(0, Number(d.menciones) || 0), 0);
  const scores = {};
  for (const d of lista) {
    const pos = Number(d.posicion) > 0 ? 1 / Number(d.posicion) : 0;
    const prom = totalMenciones > 0 ? Math.max(0, Number(d.menciones) || 0) / totalMenciones : 0;
    scores[d.marca] = (scores[d.marca] || 0) + ((pos + prom) / 2) * pesoContexto(d.sentimiento);
  }
  const total = Object.values(scores).reduce((n, v) => n + v, 0);
  const sov = {};
  for (const m of Object.keys(scores)) sov[m] = total > 0 ? Math.round((scores[m] / total) * 1000) / 10 : 0;
  return sov;
}

// Detalle aproximado para filas sin desglose por banco: el orden de
// marcas_mencionadas da la posición, una mención cada uno y contexto neutral
// salvo BCP, que usa su sentimiento.
function detalleDesdeRanking(marcas, marcaPropia, sentimientoPropio, mencionesPropias) {
  return (marcas || []).map((m, i) => ({
    marca: m,
    posicion: i + 1,
    menciones: m === marcaPropia && mencionesPropias > 0 ? mencionesPropias : 1,
    // Sin desglose no hay sentimiento de los competidores: null (desconocido), no 0.
    sentimiento: m === marcaPropia ? sentimientoPropio : null
  }));
}

// El Analista devuelve el detalle como texto JSON. Se acepta con o sin
// ```json, y si no se puede leer se devuelve [].
function leerDetalle(texto) {
  if (Array.isArray(texto)) return texto;
  const s = String(texto || '').replace(/```(json)?/gi, '').trim();
  if (!s) return [];
  try {
    const v = JSON.parse(s.slice(s.indexOf('['), s.lastIndexOf(']') + 1));
    return Array.isArray(v) ? v : [];
  } catch (e) {
    return [];
  }
}

// Arma la respuesta de /geo-dashboard a partir de las filas de la hoja
// Resultados. Sin dependencias: build.mjs lo pega en el nodo Code «Dashboard».
//
// Las filas llegan de Google Sheets como texto: «TRUE», «0,25», «3». Por eso
// todo pasa por aBool y aNum antes de sumar.

function aBool(v) {
  if (typeof v === 'boolean') return v;
  return ['true', 'verdadero', '1', 'si', 'sí', 'x'].includes(String(v || '').trim().toLowerCase());
}

function aNum(v) {
  if (typeof v === 'number') return isFinite(v) ? v : null;
  const s = String(v == null ? '' : v).trim().replace(',', '.');
  if (s === '') return null;
  const n = Number(s);
  return isFinite(n) ? n : null;
}

function aLista(v) {
  if (Array.isArray(v)) return v;
  return String(v || '').split(/[,;|]/).map(s => s.trim()).filter(Boolean);
}

function pct(a, b) {
  return b ? Math.round((a / b) * 1000) / 10 : 0;
}

function promedio(xs) {
  const v = xs.filter(x => x !== null && x !== undefined);
  return v.length ? Math.round((v.reduce((s, x) => s + x, 0) / v.length) * 100) / 100 : null;
}

function normalizarFila(f) {
  return {
    run_id: String(f.run_id || ''),
    fecha: String(f.fecha || '').slice(0, 10),
    timestamp: String(f.timestamp || ''),
    prompt_id: String(f.prompt_id || ''),
    proyecto: String(f.proyecto || '').trim() || 'Sin proyecto',
    prompt: String(f.prompt || ''),
    motor: String(f.motor || ''),
    estado: String(f.estado || '').trim(),
    disponible: f.estado !== undefined ? String(f.estado).trim() === 'ok' : aBool(f.disponible),
    menciona: aBool(f.menciona_bcp !== undefined ? f.menciona_bcp : f.menciona),
    posicion: aNum(f.posicion_bcp !== undefined ? f.posicion_bcp : f.posicion),
    sentimiento: aNum(f.sentimiento),
    citado: aBool(f.citado_bcp !== undefined ? f.citado_bcp : f.citado),
    marcas: aLista(f.marcas_mencionadas !== undefined ? f.marcas_mencionadas : f.marcas),
    fuentes: aLista(f.fuentes),
    respuesta: String(f.respuesta || ''),
    error: String(f.error || ''),
    n_menciones_bcp: aNum(f.n_menciones_bcp),
    n_menciones_bancos: aNum(f.n_menciones_bancos),
    categoria: String(f.categoria || ''),
    detalle_marcas: String(f.detalle_marcas || ''),
    sov_bcp: aNum(f.sov_bcp),
    fuentes_detalle: String(f.fuentes_detalle || ''),
    consultas_busqueda: String(f.consultas_busqueda || '')
  };
}

// Las métricas de un grupo de filas. Las filas con error no cuentan: si a un
// motor se le acabó el saldo, no es que no nos mencione.
function metricas(filas) {
  const validas = filas.filter(f => !f.error);
  const menc = validas.filter(f => f.menciona);
  return {
    total_respuestas: validas.length,
    menciones: menc.length,
    share_of_model: pct(menc.length, validas.length),
    citaciones: validas.filter(f => f.citado).length,
    tasa_citacion: pct(validas.filter(f => f.citado).length, validas.length),
    sentimiento_promedio: promedio(menc.map(f => f.sentimiento)),
    posicion_promedio: promedio(menc.map(f => f.posicion))
  };
}

// Variación en puntos porcentuales: el último día con datos contra el anterior.
function variacion(filas) {
  const fechas = [...new Set(filas.filter(f => !f.error).map(f => f.fecha))].sort();
  if (fechas.length < 2) return null;
  const ult = metricas(filas.filter(f => f.fecha === fechas[fechas.length - 1])).share_of_model;
  const ant = metricas(filas.filter(f => f.fecha === fechas[fechas.length - 2])).share_of_model;
  return Math.round((ult - ant) * 10) / 10;
}

function construirDashboard(filasCrudas, filtros, config) {
  filtros = filtros || {};
  const motores = config.motores;
  const marcaPropia = config.marca.nombre;
  const dominiosPropios = (config.marca.dominios || []).map(d => d.toLowerCase());
  const esPropio = d => dominiosPropios.some(p => d === p || d.endsWith('.' + p));

  const todas = filasCrudas
    .filter(f => f && (f.motor || f.prompt_id))
    .map(normalizarFila)
    .filter(f => motores.some(m => m.key === f.motor));

  const filas = todas.filter(f =>
    (!filtros.proyecto || f.proyecto === filtros.proyecto) &&
    (!filtros.motor || f.motor === filtros.motor) &&
    (!filtros.prompt_id || f.prompt_id === filtros.prompt_id) &&
    (!filtros.desde || f.fecha >= filtros.desde) &&
    (!filtros.hasta || f.fecha <= filtros.hasta)
  );

  const base = { motores, filtros };
  if (!filas.length) {
    return Object.assign(base, {
      vacio: !todas.length,
      kpis: Object.assign(metricas([]), {
        var_share_of_model: null, presencia_ai_overview: null,
        ultima_corrida: todas.length ? todas.map(f => f.timestamp || f.fecha).sort().pop() : null
      }),
      por_motor: [], tendencia: [], competidores: [], fuentes: [], proyectos: [], prompts: [], respuestas: []
    });
  }

  const validas = filas.filter(f => !f.error);
  const aio = validas.filter(f => f.motor === 'ai_overview');

  const kpis = Object.assign(metricas(filas), {
    var_share_of_model: variacion(filas),
    presencia_ai_overview: aio.length ? pct(aio.filter(f => f.disponible).length, aio.length) : null,
    ultima_corrida: filas.map(f => f.timestamp || f.fecha).sort().pop()
  });

  const por_motor = motores.map(m => {
    const fm = filas.filter(f => f.motor === m.key);
    const x = metricas(fm);
    return {
      motor: m.key, label: m.label,
      share_of_model: x.share_of_model, var_share_of_model: variacion(fm),
      menciones: x.menciones, total_respuestas: x.total_respuestas, citaciones: x.citaciones,
      sentimiento_promedio: x.sentimiento_promedio, posicion_promedio: x.posicion_promedio
    };
  });

  const fechas = [...new Set(validas.map(f => f.fecha))].sort();
  const tendencia = fechas.map(fecha => {
    const fd = validas.filter(f => f.fecha === fecha);
    const punto = { fecha };
    for (const m of motores) {
      const fm = fd.filter(f => f.motor === m.key);
      punto[m.key] = fm.length ? metricas(fm).share_of_model : null;
    }
    punto.total = metricas(fd).share_of_model;
    return punto;
  });

  const nombres = [marcaPropia].concat((config.competidores || []).map(c => c.nombre));
  const competidores = nombres
    .map(marca => {
      const n = validas.filter(f => f.marcas.includes(marca)).length;
      return { marca, menciones: n, share_of_model: pct(n, validas.length), es_bcp: marca === marcaPropia };
    })
    .sort((a, b) => b.menciones - a.menciones || (b.es_bcp ? 1 : 0) - (a.es_bcp ? 1 : 0))
    .map((c, i) => Object.assign({ ranking: i + 1 }, c));

  const conteo = {};
  for (const f of validas) for (const d of f.fuentes) conteo[d] = (conteo[d] || 0) + 1;
  const fuentes = Object.keys(conteo)
    .map(dominio => ({ dominio, citas: conteo[dominio], es_bcp: esPropio(dominio) }))
    .sort((a, b) => b.citas - a.citas)
    .slice(0, 30);

  const nombresProyectos = [...new Set(filas.map(f => f.proyecto))].sort();
  const proyectos = nombresProyectos.map(proyecto => {
    const fp = filas.filter(f => f.proyecto === proyecto);
    const x = metricas(fp);
    return {
      proyecto, prompts: new Set(fp.map(f => f.prompt_id)).size,
      share_of_model: x.share_of_model, var_share_of_model: variacion(fp), menciones: x.menciones
    };
  });

  // La matriz prompt × motor muestra la última respuesta válida de cada motor.
  const idsPrompts = [...new Set(filas.map(f => f.prompt_id))];
  const prompts = idsPrompts.map(id => {
    const fp = filas.filter(f => f.prompt_id === id);
    const ultima = fp.map(f => f.fecha).sort().pop();
    const mot = {};
    for (const m of motores) {
      const r = fp.filter(f => f.motor === m.key && !f.error)
        .sort((a, b) => (a.timestamp || a.fecha).localeCompare(b.timestamp || b.fecha)).pop();
      mot[m.key] = r
        ? { menciona: r.menciona, posicion: r.posicion, sentimiento: r.sentimiento, citado: r.citado, marcas: r.marcas, fecha: r.fecha, disponible: r.disponible }
        : null;
    }
    const recientes = fp.filter(f => f.fecha === ultima);
    return {
      prompt_id: id, prompt: fp[fp.length - 1].prompt, proyecto: fp[fp.length - 1].proyecto,
      share_of_model: metricas(recientes).share_of_model, ultima_fecha: ultima, motores: mot
    };
  });

  let respuestas = [];
  if (filtros.proyecto || filtros.prompt_id) {
    respuestas = filas
      .slice()
      .sort((a, b) => (b.timestamp || b.fecha).localeCompare(a.timestamp || a.fecha))
      .slice(0, 300)
      .map(f => ({
        fecha: f.fecha, timestamp: f.timestamp, motor: f.motor, prompt_id: f.prompt_id, prompt: f.prompt,
        menciona: f.menciona, posicion: f.posicion, sentimiento: f.sentimiento, citado: f.citado,
        disponible: f.disponible, marcas: f.marcas, fuentes: f.fuentes, respuesta: f.respuesta, error: f.error
      }));
  }

  return Object.assign(base, { vacio: false, kpis, por_motor, tendencia, competidores, fuentes, proyectos, prompts, respuestas });
}

// Prompts: listar (/geo-prompts), validar lo que llega a /geo-prompts-save y
// elegir cuáles entran en una corrida. Sin dependencias, como los otros dos.

// Categoría e intención son texto libre (vienen del universo de prompts de BCP).
// Estas listas solo son sugerencias para un formulario.
const CATEGORIAS = ['Reputación', 'Producto', 'Digital', 'Otra'];
const INTENCIONES = ['Informacional', 'Comparativa', 'Transaccional', 'Reputacional', 'Navegacional'];

function activoDe(v) {
  if (typeof v === 'boolean') return v;
  const s = String(v == null ? '' : v).trim().toLowerCase();
  if (s === '') return true;
  return ['true', 'verdadero', '1', 'si', 'sí', 'x'].includes(s);
}

// Etapa del funnel según la intención de búsqueda, si la hoja no la trae.
const ETAPA_POR_INTENCION = { informacional: 'tofu', comparativa: 'mofu', reputacional: 'mofu', transaccional: 'bofu', navegacional: 'bofu' };
const ETAPAS = ['tofu', 'mofu', 'bofu'];

function listaTags(v) {
  const lista = Array.isArray(v) ? v : String(v || '').split(/[,;|]/);
  return [...new Set(lista.map(t => String(t || '').trim()).filter(Boolean))];
}

function etapaDe(v, intencion) {
  const e = String(v || '').trim().toLowerCase();
  if (ETAPAS.includes(e)) return e;
  const i = String(intencion || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
  return ETAPA_POR_INTENCION[i] || 'tofu';
}

function volumenDe(v) {
  const n = Math.round(Number(v));
  return isFinite(n) && n >= 0 ? Math.min(5, n) : 0;
}

function normalizarPrompt(f) {
  return {
    id: String(f.id || '').trim(),
    proyecto: String(f.proyecto || '').trim() || 'Sin proyecto',
    prompt: String(f.prompt || '').trim(),
    categoria: String(f.categoria || '').trim() || 'Otra',
    intencion: String(f.intencion || '').trim(),
    activo: activoDe(f.activo),
    fecha_creacion: String(f.fecha_creacion || f.creado || ''),
    // Sin tags en la hoja, el proyecto hace de tag.
    tags: listaTags(f.tags).length ? listaTags(f.tags) : [String(f.proyecto || '').trim() || 'Sin proyecto'],
    etapa: etapaDe(f.etapa, f.intencion),
    volumen: volumenDe(f.volumen),
    pais: String(f.pais || '').trim().toUpperCase() || 'PE'
  };
}

function listarPrompts(filas) {
  const prompts = filas
    .filter(f => f && f.id && String(f.prompt || '').trim())
    .map(normalizarPrompt)
    .sort((a, b) => b.fecha_creacion.localeCompare(a.fecha_creacion) || b.id.localeCompare(a.id));
  const proyectos = [...new Set(prompts.map(p => p.proyecto))].sort();
  const unicos = (base, campo) => [...new Set(base.concat(prompts.map(p => p[campo]).filter(Boolean)))].sort();
  return {
    prompts, proyectos,
    categorias: unicos(CATEGORIAS, 'categoria'), intenciones: unicos(INTENCIONES, 'intencion'),
    tags: [...new Set(prompts.flatMap(p => p.tags))].sort(), etapas: ETAPAS,
    total: prompts.length, activos: prompts.filter(p => p.activo).length
  };
}

// Devuelve la fila que hay que escribir (solo con las columnas que cambian,
// para que «Agregar o actualizar» no pise fecha_creacion al editar) o un error.
// hoy: AAAA-MM-DD en Lima.
function prepararGuardado(body, hoy, idNuevo) {
  body = body || {};
  const id = String(body.id || '').trim();
  if (body.accion === 'eliminar') {
    if (!id) return { ok: false, error: 'Falta el id del prompt a eliminar.' };
    return { ok: true, accion: 'eliminar', fila: { id, activo: false } };
  }
  const prompt = String(body.prompt || '').trim();
  const fila = { id: id || idNuevo };
  if (!id || body.prompt !== undefined) {
    if (!prompt) return { ok: false, error: 'El prompt no puede estar vacío.' };
    if (prompt.length > 2000) return { ok: false, error: 'El prompt pasa de 2.000 caracteres.' };
    fila.prompt = prompt;
  }
  if (!id || body.proyecto !== undefined) fila.proyecto = String(body.proyecto || '').trim() || 'Sin proyecto';
  if (!id || body.categoria !== undefined) {
    fila.categoria = String(body.categoria || '').trim().slice(0, 80) || 'Otra';
  }
  if (body.intencion !== undefined) fila.intencion = String(body.intencion || '').trim().slice(0, 40);
  if (body.tags !== undefined) fila.tags = listaTags(body.tags).map(t => t.slice(0, 40)).slice(0, 12);
  if (body.etapa !== undefined) {
    const e = String(body.etapa || '').trim().toLowerCase();
    if (e && !ETAPAS.includes(e)) return { ok: false, error: 'La etapa debe ser tofu, mofu o bofu.' };
    fila.etapa = e;
  }
  if (body.volumen !== undefined) fila.volumen = volumenDe(body.volumen);
  if (body.pais !== undefined) fila.pais = String(body.pais || '').trim().toUpperCase().slice(0, 2) || 'PE';
  if (!id || body.activo !== undefined) fila.activo = activoDe(body.activo);
  if (!id) fila.fecha_creacion = hoy;
  return { ok: true, accion: id ? 'editar' : 'crear', fila };
}

// Qué prompts entran en la corrida: los activos, y si llegan prompt_ids o
// proyecto, solo esos. Un prompt_id pedido a mano corre aunque esté inactivo.
function elegirPrompts(filas, peticion) {
  peticion = peticion || {};
  const ids = Array.isArray(peticion.prompt_ids) ? peticion.prompt_ids.map(String) : [];
  return filas
    .filter(f => f && f.id && String(f.prompt || '').trim())
    .map(normalizarPrompt)
    .filter(p => (ids.length ? ids.includes(p.id) : p.activo))
    .filter(p => !peticion.proyecto || p.proyecto === peticion.proyecto);
}

// Arma la respuesta de /geo-monitor-data: las hojas resultados y prompts con la
// forma de DATA.monitor y DATA.prompts del front «BCP · Monitor de Visibilidad
// en IA». El front calcula sus KPIs en el navegador a partir de estas
// observaciones. Sin dependencias: build.mjs lo pega en el nodo «Datos del
// monitor» junto con config.js, sov.js, dashboard.js (normalizarFila) y prompts.js.

// Nuestra clave de motor → la del front.
const MODELO_FRONT = { chatgpt: 'chatgpt', claude: 'claude', gemini: 'gemini', perplexity: 'perplexity', ai_overview: 'overview' };

function slug(s) {
  return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
    .replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'sin-proyecto';
}

// Categoría de un dominio (SPEC v2 §5 + «comparator»): corrección del Sheet
// (_dominios) → marca propia/competidor → semilla de config.js → reglas.
const CATEGORIAS_DOMINIO = ['brand', 'competitor', 'comparator', 'government_ngo', 'news_media', 'social', 'community_forum',
  'education', 'video', 'encyclopedia', 'blog_personal', 'other', 'unclassified'];

function categoriaDominio(dominio, config, correcciones) {
  const d = String(dominio || '').toLowerCase();
  const es = lista => (lista || []).some(x => d === x || d.endsWith('.' + x));
  if (correcciones && correcciones[d]) return correcciones[d];
  if (es(config.marca.dominios)) return 'brand';
  if ((config.competidores || []).some(c => es(c.dominios))) return 'competitor';
  const semilla = config.dominios || {};
  const clave = Object.keys(semilla).find(k => d === k || d.endsWith('.' + k));
  if (clave) return semilla[clave];
  if (/(^|\.)(gob|gov|gub|mil)(\.|$)|\.int$|onu|unesco|worldbank|imf\.org/.test(d)) return 'government_ngo';
  if (/wikipedia\.org$|wikiwand|britannica/.test(d)) return 'encyclopedia';
  if (/youtube|youtu\.be|tiktok|vimeo|twitch/.test(d)) return 'video';
  if (/facebook|instagram|linkedin|(^|\.)x\.com$|twitter|threads\.net|pinterest/.test(d)) return 'social';
  if (/reddit|quora|rankia|foro|forum|stackexchange/.test(d)) return 'community_forum';
  if (/(^|\.)edu(\.|$)|universidad|\.ac\.|coursera|udemy/.test(d)) return 'education';
  if (/blogspot|wordpress\.com|medium\.com|substack/.test(d)) return 'blog_personal';
  if (/compara|ranking|mejores|kayak|finanzas?para/.test(d)) return 'comparator';
  if (/diario|noticia|news|prensa|times|post|tribune|press|journal|semana|revista|tv|radio/.test(d)) return 'news_media';
  return 'unclassified';
}

function leerJson(texto, porDefecto) {
  if (!texto) return porDefecto;
  try { const v = JSON.parse(texto); return v === null || v === undefined ? porDefecto : v; } catch (e) { return porDefecto; }
}

function etiquetaSentimiento(v) {
  if (v === null) return null;
  return v > 0.2 ? 'positivo' : v < -0.2 ? 'negativo' : 'neutral';
}

// Una fila de resultados → una observación del front.
function observacion(f, config, meta) {
  const propios = (config.marca.dominios || []).map(d => d.toLowerCase());
  const esPropio = d => propios.some(p => d === p || d.endsWith('.' + p));
  const modelId = MODELO_FRONT[f.motor];
  const projectId = slug(f.proyecto);
  const error = f.estado === 'error' || (!f.estado && Boolean(f.error));
  const menciona = !error && f.menciona;
  const marcas = f.marcas;
  const propia = config.marca.nombre;
  // Share of Voice (sov.js). Las filas sin desglose por banco (anteriores al
  // 21/10) se aproximan con el orden de marcas_mencionadas.
  let detalle = leerDetalle(f.detalle_marcas);
  if (!detalle.length && !error) detalle = detalleDesdeRanking(marcas, propia, f.sentimiento, f.n_menciones_bcp);
  const sovByBrand = error ? {} : sovPorMarca(detalle);
  const sov = error ? null : menciona ? (f.sov_bcp !== null && f.detalle_marcas ? f.sov_bcp : (sovByBrand[propia] || 0)) : 0;
  // Proporción de menciones (la métrica anterior), por si se quiere comparar.
  const mentionShare = menciona && f.n_menciones_bancos > 0 && f.n_menciones_bcp > 0
    ? Math.round(Math.min(100, (f.n_menciones_bcp / f.n_menciones_bancos) * 100) * 10) / 10
    : menciona ? Math.round((100 / Math.max(1, marcas.length)) * 10) / 10 : 0;
  // Citas con URL y título (filas desde el 21/10); antes solo había dominios.
  const detalleFuentes = leerJson(f.fuentes_detalle, []);
  const sources = Array.isArray(detalleFuentes) && detalleFuentes.length
    ? detalleFuentes.filter(c => c && c.domain).map((c, i) => ({ domain: c.domain, url: c.url || 'https://' + c.domain + '/', title: c.title || '', position: c.position || i + 1 }))
    : f.fuentes.map((d, i) => ({ domain: d, url: 'https://' + d + '/', title: '', position: i + 1 }));
  // Histórico de Trinity: solo se sabe si citó viabcp.com (y cuántas veces), no
  // qué otras fuentes usó. Esas filas no entran en el mix de fuentes ni en el
  // explorador de URLs; cuentan en «citas de dominio propio».
  const trinity = String(f.run_id || '').startsWith('trinity_');
  const citasPropias = sources.filter(c => esPropio(c.domain)).length;
  if (trinity) sources.length = 0;
  const idxPropio = sources.findIndex(c => esPropio(c.domain));
  const sentimiento = menciona && f.sentimiento !== null ? f.sentimiento : null;
  return {
    id: [projectId, modelId, f.prompt_id, f.fecha].join(':'),
    projectId,
    modelId,
    promptId: f.prompt_id,
    date: f.fecha,
    timestamp: f.timestamp,
    status: error ? 'error' : menciona ? 'ok' : 'not_mentioned',
    // El front promedia `som` en su KPI principal: lleva el Share of Voice.
    som: sov,
    sov,
    sovByBrand,
    brandDetail: detalle,
    mentionShare: error ? null : mentionShare,
    category: (meta && meta.categoria) || f.categoria || '',
    intent: (meta && meta.intencion) || '',
    position: menciona ? f.posicion : null,
    linkPosition: idxPropio >= 0 ? idxPropio + 1 : null,
    mentions: menciona ? (f.n_menciones_bcp || 1) : 0,
    citations: citasPropias,
    sentiment: sentimiento,
    sentimentLabel: etiquetaSentimiento(sentimiento),
    blockAppeared: modelId === 'overview' ? (!error && f.estado !== 'sin_overview') : null,
    brandMentioned: menciona,
    brandCited: !error && f.citado,
    sources,
    sourcesComplete: !trinity,
    searchQueries: leerJson(f.consultas_busqueda, []),
    country: (meta && meta.pais) || 'PE',
    tags: (meta && meta.tags) || [],
    ranking: marcas,
    response: f.respuesta.length > MAX_RESPUESTA ? f.respuesta.slice(0, MAX_RESPUESTA) + '…' : f.respuesta,
    error: f.error,
    isExample: false,
    // Las filas importadas del histórico de Trinity (Pymes) llevan run_id «trinity_…».
    source: trinity ? 'Trinity · histórico importado' : 'n8n · GEO Tracker'
  };
}

// El front muestra como mucho 6 meses; más atrás no se manda.
const DIAS_HISTORIA = 190;
// La respuesta completa queda en el Sheet; al front le basta con esto.
const MAX_RESPUESTA = 4000;

function construirMonitor(filasResultados, filasPrompts, config, hoy, sistema) {
  sistema = sistema || {};
  const desde = new Date(new Date(hoy + 'T12:00:00Z').getTime() - DIAS_HISTORIA * 864e5).toISOString().slice(0, 10);
  const metaPrompts = new Map(filasPrompts.filter(f => f && f.id).map(f => [String(f.id).trim(), normalizarPrompt(f)]));
  // Varias corridas el mismo día: se queda la última de cada prompt y motor.
  const porId = new Map();
  for (const crudo of filasResultados) {
    if (!crudo || !crudo.motor) continue;
    const f = normalizarFila(crudo);
    if (!MODELO_FRONT[f.motor] || !f.prompt_id || !f.fecha || f.fecha < desde) continue;
    const o = observacion(f, config, metaPrompts.get(f.prompt_id));
    const previa = porId.get(o.id);
    if (!previa || String(previa.timestamp) < String(o.timestamp)) porId.set(o.id, o);
  }
  const observations = [...porId.values()].sort((a, b) => a.date.localeCompare(b.date) || a.id.localeCompare(b.id));

  const prompts = filasPrompts.filter(f => f && f.id && String(f.prompt || '').trim()).map(normalizarPrompt);
  // Los proyectos salen de la hoja prompts (activos o con observaciones).
  const conDatos = new Set(observations.map(o => o.promptId));
  const proyectos = new Map();
  for (const p of prompts) {
    if (!p.activo && !conDatos.has(p.id)) continue;
    const id = slug(p.proyecto);
    if (!proyectos.has(id)) proyectos.set(id, { id, name: p.proyecto, promptIds: [], categorias: new Set() });
    const pr = proyectos.get(id);
    pr.promptIds.push(p.id);
    pr.categorias.add(p.categoria);
  }
  // Lo que ya tiene observaciones tiene que existir aunque la hoja prompts haya
  // cambiado (prompt borrado o movido de proyecto): el front busca ambos por id.
  const promptsVistos = new Set(prompts.map(p => p.id));
  const extra = [];
  for (const crudo of filasResultados) {
    if (!crudo || !crudo.motor || !crudo.prompt_id) continue;
    const f = normalizarFila(crudo);
    const id = slug(f.proyecto);
    if (!proyectos.has(id)) proyectos.set(id, { id, name: f.proyecto, promptIds: [], categorias: new Set() });
    const pr = proyectos.get(id);
    if (!pr.promptIds.includes(f.prompt_id)) pr.promptIds.push(f.prompt_id);
    if (crudo.categoria) pr.categorias.add(String(crudo.categoria));
    if (!promptsVistos.has(f.prompt_id)) {
      promptsVistos.add(f.prompt_id);
      extra.push({ id: f.prompt_id, proyecto: f.proyecto, prompt: f.prompt, categoria: String(crudo.categoria || 'Otra'), activo: false });
    }
  }
  prompts.push(...extra);

  const projects = [...proyectos.values()].map(p => ({
    id: p.id,
    name: p.name,
    description: `${p.promptIds.length} prompt${p.promptIds.length === 1 ? '' : 's'} · ${p.categorias.size} categoría${p.categorias.size === 1 ? '' : 's'}`,
    promptIds: p.promptIds,
    example: false
  }));

  const conteo = new Map();
  for (const o of observations) for (const s of o.sources) conteo.set(s.domain, (conteo.get(s.domain) || 0) + 1);
  const domains = [...conteo.entries()].sort((a, b) => b[1] - a[1]).slice(0, 30).map(([d]) => [d, 'https://' + d + '/']);

  // Categoría de cada dominio citado, con las correcciones de la pestaña _dominios.
  const correcciones = {};
  for (const f of sistema._dominios || []) {
    const d = String(f.dominio || '').trim().toLowerCase();
    if (d && CATEGORIAS_DOMINIO.includes(String(f.categoria || '').trim())) correcciones[d] = String(f.categoria).trim();
  }
  const domainCategories = {};
  for (const d of conteo.keys()) domainCategories[d] = categoriaDominio(d, config, correcciones);

  const recStates = {};
  for (const f of sistema._recomendaciones || []) {
    if (f.id) recStates[f.id] = { status: f.estado || 'suggested', owner: f.responsable || '', dueDate: fechaTexto(f.fecha_objetivo), doneAt: fechaTexto(f.fecha_hecha), updatedAt: String(f.actualizado || '') };
  }
  const audits = (sistema._auditorias || []).map(f => ({ id: String(f.id || ''), type: f.tipo, url: f.url, executedAt: String(f.fecha || ''), result: leerJson(f.resultado, null) }))
    .filter(a => a.id && a.result).sort((a, b) => b.executedAt.localeCompare(a.executedAt)).slice(0, 40);

  const marcas = [config.marca].concat(config.competidores || []);
  const brands = marcas.map((m, i) => ({
    id: slug(m.nombre), name: m.nombre, isOwn: i === 0, domains: m.dominios || [], aliases: m.alias || [], color: m.color || '#94a3b8'
  }));
  const aliasPropios = (config.marca.alias || []).map(a => a.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase());
  const esBranded = texto => {
    const t = ' ' + String(texto || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ') + ' ';
    return aliasPropios.some(a => t.includes(' ' + a.replace(/[^a-z0-9]+/g, ' ').trim() + ' '));
  };

  return {
    ok: true,
    generado: new Date().toISOString(),
    monitor: {
      projects,
      observations,
      referenceDate: hoy,
      dates: [...new Set(observations.map(o => o.date))].sort(),
      domains,
      domainCategories,
      brands,
      attributes: config.atributos || [],
      recStates,
      audits
    },
    prompts: prompts.map(p => ({
      id: p.id, text: p.prompt, project: slug(p.proyecto), category: p.categoria, intent: p.intencion, active: p.activo,
      tags: p.tags, funnelStage: p.etapa, intentVolume: p.volumen, country: p.pais, isBranded: esBranded(p.prompt), createdAt: p.fecha_creacion,
      status: 'ok', position: null, linkPosition: null, sov: null, ranking: [],
      response: { isExample: false, screenshotUrl: null, text: '' }
    }))
  };
}

// Ajustes editables desde Configuración del front. Se guardan en la pestaña
// «_config» del Sheet (clave · valor JSON) y se combinan con CONFIG
// (config.js), que queda como valor por defecto. Sin dependencias: build.mjs
// lo pega en «Elegir prompts», «Datos del monitor» y el guardado.

const DIAS_SEMANA = ['lun', 'mar', 'mie', 'jue', 'vie', 'sab', 'dom'];
const AJUSTES_POR_DEFECTO = {
  monitor: { nombre: 'BCP · Monitor de Visibilidad en IA', organizacion: 'BCP · Marketing y Comunicaciones', pais: 'PE' },
  // La corrida automática: el disparador de n8n revisa cada hora si toca.
  automatizacion: { activa: true, hora: 7, dias: DIAS_SEMANA.slice() },
  // Claude busca en la web antes de responder (como las apps de los motores).
  captura: { buscar_siempre: true }
};
const PAISES_CONTEXTO = { PE: { pais: 'Perú', ciudad: 'Lima' } };

// Filas de la pestaña _config → {clave: valor}
function leerAjustes(filas) {
  const salida = {};
  for (const f of filas || []) {
    const clave = String(f.clave || '').trim();
    if (!clave) continue;
    try { salida[clave] = JSON.parse(f.valor); } catch (e) { /* valor roto: se ignora */ }
  }
  return salida;
}

const listaTexto = (v, max) => (Array.isArray(v) ? v : String(v || '').split(/[,\n]/))
  .map(x => String(x).trim()).filter(Boolean).filter((x, i, a) => a.indexOf(x) === i).slice(0, max);
const dominioLimpio = d => String(d || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
const COLORES_EXTRA = ['#c026d3', '#f97316', '#0f766e', '#be123c', '#2563eb', '#65a30d', '#7c3aed', '#0891b2'];

// Valida y normaliza un ajuste. → {ok, valor} | {ok: false, error}
function validarAjuste(clave, valor, config) {
  if (clave === 'monitor') {
    const v = valor || {};
    const nombre = String(v.nombre || '').trim().slice(0, 80), organizacion = String(v.organizacion || '').trim().slice(0, 80);
    if (!nombre) return { ok: false, error: 'El nombre del monitor no puede estar vacío.' };
    return { ok: true, valor: { nombre, organizacion, pais: String(v.pais || 'PE').toUpperCase().slice(0, 2) } };
  }
  if (clave === 'automatizacion') {
    const v = valor || {};
    const hora = Math.round(Number(v.hora));
    if (!(hora >= 0 && hora <= 23)) return { ok: false, error: 'La hora debe estar entre 0 y 23.' };
    const dias = listaTexto(v.dias, 7).filter(d => DIAS_SEMANA.includes(d));
    if (v.activa !== false && !dias.length) return { ok: false, error: 'Elige al menos un día.' };
    return { ok: true, valor: { activa: v.activa !== false, hora, dias } };
  }
  if (clave === 'captura') {
    return { ok: true, valor: { buscar_siempre: !(valor && valor.buscar_siempre === false) } };
  }
  if (clave === 'marca') {
    const v = valor || {};
    const alias = listaTexto(v.alias, 15);
    const dominios = listaTexto(v.dominios, 10).map(dominioLimpio).filter(Boolean);
    if (!dominios.length) return { ok: false, error: 'La marca necesita al menos un dominio propio.' };
    // El nombre de la marca no se edita: es la llave de todo el historial.
    return { ok: true, valor: { alias: [config.marca.nombre].concat(alias.filter(a => a !== config.marca.nombre)), dominios } };
  }
  if (clave === 'competidores') {
    if (!Array.isArray(valor)) return { ok: false, error: 'La lista de competidores no es válida.' };
    const vistos = new Set();
    const lista = [];
    for (const c of valor.slice(0, 25)) {
      const nombre = String((c && c.nombre) || '').trim().slice(0, 60);
      if (!nombre || vistos.has(nombre.toLowerCase()) || nombre === config.marca.nombre) continue;
      vistos.add(nombre.toLowerCase());
      const previo = (config.competidores || []).find(x => x.nombre === nombre);
      lista.push({
        nombre,
        alias: [nombre].concat(listaTexto(c.alias, 10).filter(a => a !== nombre)),
        dominios: listaTexto(c.dominios, 6).map(dominioLimpio).filter(Boolean),
        color: /^#[0-9a-f]{6}$/i.test(c.color || '') ? c.color : (previo && previo.color) || COLORES_EXTRA[lista.length % COLORES_EXTRA.length]
      });
    }
    if (!lista.length) return { ok: false, error: 'Agrega al menos un competidor.' };
    return { ok: true, valor: lista };
  }
  return { ok: false, error: 'Ajuste desconocido: ' + clave };
}

// CONFIG + ajustes guardados = la configuración con la que se mide.
function configEfectiva(config, ajustes) {
  ajustes = ajustes || {};
  const c = Object.assign({}, config);
  const marca = ajustes.marca && validarAjuste('marca', ajustes.marca, config);
  if (marca && marca.ok) c.marca = Object.assign({}, config.marca, marca.valor);
  const comp = ajustes.competidores && validarAjuste('competidores', ajustes.competidores, config);
  if (comp && comp.ok) c.competidores = comp.valor;
  return c;
}

function ajustesVigentes(ajustes, config) {
  const a = ajustes || {};
  const c = configEfectiva(config, a);
  const auto = a.automatizacion && validarAjuste('automatizacion', a.automatizacion, config);
  const mon = a.monitor && validarAjuste('monitor', a.monitor, config);
  const cap = a.captura && validarAjuste('captura', a.captura, config);
  return {
    monitor: mon && mon.ok ? mon.valor : AJUSTES_POR_DEFECTO.monitor,
    automatizacion: auto && auto.ok ? auto.valor : AJUSTES_POR_DEFECTO.automatizacion,
    captura: cap && cap.ok ? cap.valor : AJUSTES_POR_DEFECTO.captura,
    marca: { nombre: c.marca.nombre, alias: c.marca.alias, dominios: c.marca.dominios },
    competidores: c.competidores.map(x => ({ nombre: x.nombre, alias: x.alias, dominios: x.dominios, color: x.color }))
  };
}

// ¿Le toca correr a la corrida programada en este momento (hora de Lima)?
function tocaCorrer(automatizacion, fecha) {
  const a = Object.assign({}, AJUSTES_POR_DEFECTO.automatizacion, automatizacion || {});
  if (a.activa === false) return false;
  const partes = new Intl.DateTimeFormat('en-US', { timeZone: 'America/Lima', hour: 'numeric', hourCycle: 'h23', weekday: 'short' }).formatToParts(fecha || new Date());
  const hora = Number((partes.find(p => p.type === 'hour') || {}).value);
  const dia = { Mon: 'lun', Tue: 'mar', Wed: 'mie', Thu: 'jue', Fri: 'vie', Sat: 'sab', Sun: 'dom' }[(partes.find(p => p.type === 'weekday') || {}).value];
  return hora === Number(a.hora) && (a.dias || []).includes(dia);
}

// Lista de bancos para el Analista: «BCP (Banco de Crédito del Perú, ViaBCP); …»
function marcasParaAnalista(config) {
  return [config.marca].concat(config.competidores || [])
    .map(m => `${m.nombre} (${(m.alias || []).filter(a => a !== m.nombre).join(', ') || 'sin alias'})`).join('; ');
}

// Línea de sistema que da a cada motor el país del usuario (las APIs no
// geolocalizan como la app: sin esto, Claude preguntó «¿en qué país estás?»).
function contextoPais(codigo) {
