function cuerpoLectura(meta, { prompts = false, resultadosDesde = null, sistema = false } = {}) {
  const filtros = [];
  for (const p of pestanas(meta)) {
    if (prompts && esPestanaProyecto(p.titulo)) filtros.push({ a1Range: rango(p.titulo, 'A:J') });
    if (resultadosDesde && esPestanaFecha(p.titulo) && p.titulo >= resultadosDesde) filtros.push({ a1Range: rango(p.titulo, 'A:W') });
    if (sistema && SISTEMA.includes(p.titulo)) filtros.push({ a1Range: rango(p.titulo, 'A:H') });
  }
  // La API no acepta una lista vacía: sin nada que leer, se pide A1 de la primera pestaña.
  const primera = pestanas(meta)[0];
  if (!filtros.length && primera) filtros.push({ a1Range: rango(primera.titulo, 'A1:A1') });
  return { dataFilters: filtros, majorDimension: 'ROWS', valueRenderOption: 'UNFORMATTED_VALUE' };
}

function tituloDeRango(r) {
  const m = String(r || '').match(/^'((?:[^']|'')*)'!/) || String(r || '').match(/^([^!]+)!/);
  return m ? m[1].replace(/''/g, "'") : '';
}

function claveColumna(c) {
  const k = String(c || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
  if (k === 'id') return 'id';
  if (k.startsWith('categ')) return 'categoria';
  if (k.startsWith('intenc')) return 'intencion';
  if (k.startsWith('prompt')) return 'prompt';
  if (k.startsWith('activo')) return 'activo';
  if (k.startsWith('fecha')) return 'fecha_creacion';
  if (k === 'tags' || k === 'tag') return 'tags';
  if (k.startsWith('etapa') || k.startsWith('funnel')) return 'etapa';
  if (k.startsWith('volumen')) return 'volumen';
  if (k === 'pais' || k === 'country') return 'pais';
  return '';
}

// Respuesta de batchGetByDataFilter → {prompts, resultados, sistema}.
// Cada prompt lleva su pestaña (= proyecto) y su número de fila.
function leerHojas(respuesta) {
  const prompts = [];
  const resultados = [];
  const sistema = {};
  for (const vr of (respuesta && respuesta.valueRanges) || []) {
    const v = vr.valueRange || vr;
    const titulo = tituloDeRango(v.range);
    const filas = v.values || [];
    if (!filas.length) continue;
    if (SISTEMA.includes(titulo)) {
      const cab = filas[0].map(String);
      sistema[titulo] = [];
      filas.slice(1).forEach((f, i) => {
        if (!f || !f.some(x => x !== '' && x !== null)) return;
        const o = { _fila: i + 2 };
        cab.forEach((c, j) => { o[c] = f[j] === undefined ? '' : f[j]; });
        sistema[titulo].push(o);
      });
    } else if (esPestanaFecha(titulo)) {
      const cab = filas[0].map(String);
      filas.slice(1).forEach(f => {
        if (!f || !f.some(x => x !== '' && x !== null)) return;
        const o = {};
        cab.forEach((c, i) => { o[c] = f[i] === undefined ? '' : f[i]; });
        resultados.push(o);
      });
    } else if (esPestanaProyecto(titulo)) {
      const cab = filas[0].map(claveColumna);
      filas.slice(1).forEach((f, i) => {
        if (!f || !f.some(x => x !== '' && x !== null)) return;
        const o = { proyecto: titulo, _fila: i + 2 };
        cab.forEach((c, j) => { if (c) o[c] = f[j] === undefined ? '' : f[j]; });
        if (o.fecha_creacion !== undefined) o.fecha_creacion = fechaTexto(o.fecha_creacion);
        prompts.push(o);
      });
    }
  }
  return { prompts, resultados, sistema };
}

// Las fechas pueden volver como número de serie de Sheets (UNFORMATTED_VALUE).
function fechaTexto(v) {
  if (typeof v === 'number' && v > 20000 && v < 80000) {
    return new Date(Date.UTC(1899, 11, 30) + v * 864e5).toISOString().slice(0, 10);
  }
  return String(v || '');
}

function valoresPrompt(p) {
  return [p.id, p.categoria || '', p.intencion || '', p.prompt || '', p.activo === false ? 'FALSE' : 'TRUE', p.fecha_creacion || '',
    (p.tags || []).join(', '), p.etapa || '', p.volumen ? p.volumen : '', p.pais || 'PE'];
}

function valoresResultado(f) {
  return COLUMNAS_RESULTADOS.map(c => {
    const v = f[c];
    return v === undefined || v === null ? '' : typeof v === 'boolean' ? (v ? 'TRUE' : 'FALSE') : v;
  });
}

// ─── Peticiones a la API de Sheets ─────────────────────────────────────────
const pedidoSheets = (method, ruta, body) => ({ method, url: SHEETS_API + ruta, body });
// Crea la pestaña y escribe sus filas en UNA sola petición (addSheet + appendCells
// con un sheetId elegido aquí). Con dos peticiones separadas, n8n las lanza con
// 300 ms de diferencia sin esperar la primera y la escritura puede llegar antes
// que la pestaña («Unable to parse range»): pasó en la corrida del 21/10.
function crearPestana(titulo, indice, filas, meta) {
  const usados = pestanas(meta).map(t => Number(t.id) || 0);
  let id = (Math.max(0, ...usados) % 2000000000) + 1;
  while (usados.includes(id)) id++;
  const celda = v => ({ userEnteredValue: typeof v === 'number' ? { numberValue: v } : typeof v === 'boolean' ? { boolValue: v } : { stringValue: v === null || v === undefined ? '' : String(v) } });
  const requests = [{ addSheet: { properties: Object.assign({ sheetId: id, title: titulo }, indice === undefined ? {} : { index: indice }) } }];
  if (filas && filas.length) requests.push({ appendCells: { sheetId: id, rows: filas.map(f => ({ values: f.map(celda) })), fields: 'userEnteredValue' } });
  return pedidoSheets('POST', ':batchUpdate', { requests });
}
const escribir = (titulo, desde, valores) =>
  pedidoSheets('PUT', '/values/' + encodeURIComponent(rango(titulo, desde)) + '?valueInputOption=RAW', { values: valores });
const agregar = (titulo, valores) =>
  pedidoSheets('POST', '/values/' + encodeURIComponent(rango(titulo, 'A1')) + ':append?valueInputOption=RAW&insertDataOption=INSERT_ROWS', { values: valores });
const borrarFila = (idPestana, fila) =>
  pedidoSheets('POST', ':batchUpdate', { requests: [{ deleteDimension: { range: { sheetId: idPestana, dimension: 'ROWS', startIndex: fila - 1, endIndex: fila } } }] });

// Crear, editar, activar/desactivar, mover de proyecto o eliminar un prompt.
// guardado: lo que devuelve prepararGuardado (prompts.js).
// → {ok, status, respuesta, peticiones}
function planGuardarPrompt(guardado, prompts, meta) {
  if (!guardado.ok) return { ok: false, status: 400, respuesta: { ok: false, error: guardado.error }, peticiones: [] };
  const tabs = pestanas(meta);
  const tab = titulo => tabs.find(t => t.titulo === titulo);
  const fila = guardado.fila;
  const actual = prompts.find(p => String(p.id).trim() === fila.id);
  const proyectosAlFinal = tabs.filter(t => esPestanaProyecto(t.titulo)).length;
  // Agrega filas a la pestaña del proyecto; si no existe, la crea con encabezados y filas a la vez.
  const agregarEn = (titulo, valores, pet) => {
    pet.push(tab(titulo) ? agregar(titulo, valores) : crearPestana(titulo, proyectosAlFinal, [COLUMNAS_PROMPTS].concat(valores), meta));
  };

  if (guardado.accion === 'eliminar') {
    if (!actual) return { ok: false, status: 404, respuesta: { ok: false, error: 'No existe el prompt ' + fila.id }, peticiones: [] };
    return { ok: true, status: 200, respuesta: { ok: true, accion: 'eliminar', id: fila.id }, peticiones: [borrarFila(tab(actual.proyecto).id, actual._fila)] };
  }

  if (guardado.accion === 'editar') {
    if (!actual) return { ok: false, status: 404, respuesta: { ok: false, error: 'No existe el prompt ' + fila.id }, peticiones: [] };
    // Se combina antes de normalizar, para que lo derivado (etapa según intención) use lo nuevo.
    const nuevo = normalizarPrompt(Object.assign({}, actual, fila));
    const pet = [];
    if (nuevo.proyecto === actual.proyecto) {
      pet.push(escribir(actual.proyecto, 'A' + actual._fila + ':J' + actual._fila, [valoresPrompt(nuevo)]));
    } else {
      // Cambio de proyecto: se agrega en la pestaña nueva y se borra de la vieja.
      agregarEn(nuevo.proyecto, [valoresPrompt(nuevo)], pet);
      pet.push(borrarFila(tab(actual.proyecto).id, actual._fila));
    }
    return { ok: true, status: 200, respuesta: { ok: true, accion: 'editar', prompt: limpio(nuevo) }, peticiones: pet };
  }

  // Crear: un proyecto nuevo crea su pestaña.
  const nuevo = normalizarPrompt(fila);
  const pet = [];
  agregarEn(nuevo.proyecto, [valoresPrompt(nuevo)], pet);
  return { ok: true, status: 200, respuesta: { ok: true, accion: 'crear', prompt: limpio(nuevo) }, peticiones: pet };
}

function limpio(p) {
  const o = {};
  for (const k of Object.keys(p)) if (!k.startsWith('_')) o[k] = p[k];
  return o;
}

// Guardar las filas de una corrida en la pestaña del día (se crea si no está,
// justo después de las pestañas de proyecto, para que la más reciente quede primero).
function planGuardarResultados(filas, meta) {
  const porFecha = new Map();
  for (const f of filas) {
    if (!porFecha.has(f.fecha)) porFecha.set(f.fecha, []);
    porFecha.get(f.fecha).push(valoresResultado(f));
  }
  const tabs = pestanas(meta);
  const proyectos = tabs.filter(t => esPestanaProyecto(t.titulo)).length;
  const pet = [];
  for (const [fecha, valores] of porFecha) {
    if (tabs.some(t => t.titulo === fecha)) pet.push(agregar(fecha, valores));
    else {
      pet.push(crearPestana(fecha, proyectos, [COLUMNAS_RESULTADOS].concat(valores), meta));
    }
  }
  return pet;
}

// ─── Pestañas de sistema (_recomendaciones, _dominios, _auditorias) ─────────
const COLUMNAS_SISTEMA = {
  _recomendaciones: ['id', 'estado', 'responsable', 'fecha_objetivo', 'fecha_hecha', 'actualizado'],
  _dominios: ['dominio', 'categoria', 'actualizado'],
  _auditorias: ['id', 'tipo', 'url', 'fecha', 'resultado'],
  _config: ['clave', 'valor', 'actualizado']
};

// Agrega o actualiza el registro cuya columna `clave` coincide. Crea la pestaña
// (al final del Sheet) si todavía no existe.
function planUpsertSistema(titulo, registro, clave, filas, meta) {
  const columnas = COLUMNAS_SISTEMA[titulo];
  const valores = columnas.map(c => registro[c] === undefined || registro[c] === null ? '' : registro[c]);
  const existe = pestanas(meta).some(t => t.titulo === titulo);
  if (!existe) return [crearPestana(titulo, undefined, [columnas, valores], meta)];
  const actual = (filas || []).find(f => String(f[clave]).trim() === String(registro[clave]).trim());
  if (!actual) return [agregar(titulo, [valores])];
  const fin = String.fromCharCode(64 + columnas.length);
  const combinado = columnas.map((c, i) => (registro[c] === undefined ? (actual[c] === undefined ? '' : actual[c]) : valores[i]));
  return [escribir(titulo, 'A' + actual._fila + ':' + fin + actual._fila, [combinado])];
}

const ESTADOS_RECOMENDACION = ['suggested', 'todo', 'in_progress', 'done', 'archived'];

// POST /geo-recs-save: {id, estado, responsable?, fecha_objetivo?}
function planGuardarRecomendacion(body, filas, meta, ahora) {
  body = body || {};
  const id = String(body.id || '').trim();
  if (!id) return { ok: false, status: 400, respuesta: { ok: false, error: 'Falta el id de la recomendación.' }, peticiones: [] };
  const estado = body.estado === undefined ? undefined : String(body.estado).trim();
  if (estado !== undefined && !ESTADOS_RECOMENDACION.includes(estado)) {
    return { ok: false, status: 400, respuesta: { ok: false, error: 'Estado no válido: ' + estado }, peticiones: [] };
  }
  const previo = (filas || []).find(f => String(f.id).trim() === id);
  const registro = { id, actualizado: ahora };
  if (estado !== undefined) registro.estado = estado;
  if (body.responsable !== undefined) registro.responsable = String(body.responsable || '').trim().slice(0, 80);
  if (body.fecha_objetivo !== undefined) registro.fecha_objetivo = String(body.fecha_objetivo || '').slice(0, 10);
  // Al pasar a «hecha» se guarda la fecha, para medir el impacto después.
  if (estado === 'done' && !(previo && previo.fecha_hecha)) registro.fecha_hecha = ahora.slice(0, 10);
  if (!previo && registro.estado === undefined) registro.estado = 'suggested';
  return { ok: true, status: 200, respuesta: { ok: true, recomendacion: registro }, peticiones: planUpsertSistema('_recomendaciones', registro, 'id', filas, meta) };
}

// POST /geo-domain-save: {dominio, categoria}
function planGuardarDominio(body, filas, meta, ahora, categorias) {
  body = body || {};
  const dominio = String(body.dominio || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
  const categoria = String(body.categoria || '').trim();
  if (!dominio) return { ok: false, status: 400, respuesta: { ok: false, error: 'Falta el dominio.' }, peticiones: [] };
  if (!categorias.includes(categoria)) return { ok: false, status: 400, respuesta: { ok: false, error: 'Categoría no válida: ' + categoria }, peticiones: [] };
  const registro = { dominio, categoria, actualizado: ahora };
  return { ok: true, status: 200, respuesta: { ok: true, dominio: registro }, peticiones: planUpsertSistema('_dominios', registro, 'dominio', filas, meta) };
}

// Arma la respuesta de /geo-monitor-data: las hojas resultados y prompts con la
// forma de DATA.monitor y DATA.prompts del front «BCP · Monitor de Visibilidad
// en IA». El front calcula sus KPIs en el navegador a partir de estas
// observaciones. Sin dependencias: build.mjs lo pega en el nodo «Datos del
// monitor» junto con config.js, sov.js, dashboard.js (normalizarFila) y prompts.js.

// Nuestra clave de motor → la del front.
const MODELO_FRONT = { chatgpt: 'chatgpt', claude: 'claude', gemini: 'gemini', perplexity: 'perplexity', ai_overview: 'overview' };

function slug(s) {
  return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
    .replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'sin-proyecto';
}

// Categoría de un dominio (SPEC v2 §5 + «comparator»): corrección del Sheet
// (_dominios) → marca propia/competidor → semilla de config.js → reglas.
const CATEGORIAS_DOMINIO = ['brand', 'competitor', 'comparator', 'government_ngo', 'news_media', 'social', 'community_forum',
  'education', 'video', 'encyclopedia', 'blog_personal', 'other', 'unclassified'];

function categoriaDominio(dominio, config, correcciones) {
  const d = String(dominio || '').toLowerCase();
  const es = lista => (lista || []).some(x => d === x || d.endsWith('.' + x));
  if (correcciones && correcciones[d]) return correcciones[d];
  if (es(config.marca.dominios)) return 'brand';
  if ((config.competidores || []).some(c => es(c.dominios))) return 'competitor';
  const semilla = config.dominios || {};
  const clave = Object.keys(semilla).find(k => d === k || d.endsWith('.' + k));
  if (clave) return semilla[clave];
  if (/(^|\.)(gob|gov|gub|mil)(\.|$)|\.int$|onu|unesco|worldbank|imf\.org/.test(d)) return 'government_ngo';
  if (/wikipedia\.org$|wikiwand|britannica/.test(d)) return 'encyclopedia';
  if (/youtube|youtu\.be|tiktok|vimeo|twitch/.test(d)) return 'video';
  if (/facebook|instagram|linkedin|(^|\.)x\.com$|twitter|threads\.net|pinterest/.test(d)) return 'social';
  if (/reddit|quora|rankia|foro|forum|stackexchange/.test(d)) return 'community_forum';
  if (/(^|\.)edu(\.|$)|universidad|\.ac\.|coursera|udemy/.test(d)) return 'education';
  if (/blogspot|wordpress\.com|medium\.com|substack/.test(d)) return 'blog_personal';
  if (/compara|ranking|mejores|kayak|finanzas?para/.test(d)) return 'comparator';
  if (/diario|noticia|news|prensa|times|post|tribune|press|journal|semana|revista|tv|radio/.test(d)) return 'news_media';
  return 'unclassified';
}

function leerJson(texto, porDefecto) {
  if (!texto) return porDefecto;
  try { const v = JSON.parse(texto); return v === null || v === undefined ? porDefecto : v; } catch (e) { return porDefecto; }
}

function etiquetaSentimiento(v) {
  if (v === null) return null;
  return v > 0.2 ? 'positivo' : v < -0.2 ? 'negativo' : 'neutral';
}

// Una fila de resultados → una observación del front.
function observacion(f, config, meta) {
  const propios = (config.marca.dominios || []).map(d => d.toLowerCase());
  const esPropio = d => propios.some(p => d === p || d.endsWith('.' + p));
  const modelId = MODELO_FRONT[f.motor];
  const projectId = slug(f.proyecto);
  const error = f.estado === 'error' || (!f.estado && Boolean(f.error));
  const menciona = !error && f.menciona;
  const marcas = f.marcas;
  const propia = config.marca.nombre;
  // Share of Voice (sov.js). Las filas sin desglose por banco (anteriores al
  // 21/10) se aproximan con el orden de marcas_mencionadas.
  let detalle = leerDetalle(f.detalle_marcas);
  if (!detalle.length && !error) detalle = detalleDesdeRanking(marcas, propia, f.sentimiento, f.n_menciones_bcp);
  const sovByBrand = error ? {} : sovPorMarca(detalle);
  const sov = error ? null : menciona ? (f.sov_bcp !== null && f.detalle_marcas ? f.sov_bcp : (sovByBrand[propia] || 0)) : 0;
  // Proporción de menciones (la métrica anterior), por si se quiere comparar.
  const mentionShare = menciona && f.n_menciones_bancos > 0 && f.n_menciones_bcp > 0
    ? Math.round(Math.min(100, (f.n_menciones_bcp / f.n_menciones_bancos) * 100) * 10) / 10
    : menciona ? Math.round((100 / Math.max(1, marcas.length)) * 10) / 10 : 0;
  // Citas con URL y título (filas desde el 21/10); antes solo había dominios.
  const detalleFuentes = leerJson(f.fuentes_detalle, []);
  const sources = Array.isArray(detalleFuentes) && detalleFuentes.length
    ? detalleFuentes.filter(c => c && c.domain).map((c, i) => ({ domain: c.domain, url: c.url || 'https://' + c.domain + '/', title: c.title || '', position: c.position || i + 1 }))
    : f.fuentes.map((d, i) => ({ domain: d, url: 'https://' + d + '/', title: '', position: i + 1 }));
  // Histórico de Trinity: solo se sabe si citó viabcp.com (y cuántas veces), no
  // qué otras fuentes usó. Esas filas no entran en el mix de fuentes ni en el
  // explorador de URLs; cuentan en «citas de dominio propio».
  const trinity = String(f.run_id || '').startsWith('trinity_');
  const citasPropias = sources.filter(c => esPropio(c.domain)).length;
  if (trinity) sources.length = 0;
  const idxPropio = sources.findIndex(c => esPropio(c.domain));
  const sentimiento = menciona && f.sentimiento !== null ? f.sentimiento : null;
  return {
    id: [projectId, modelId, f.prompt_id, f.fecha].join(':'),
    projectId,
    modelId,
    promptId: f.prompt_id,
    date: f.fecha,
    timestamp: f.timestamp,
    status: error ? 'error' : menciona ? 'ok' : 'not_mentioned',
    // El front promedia `som` en su KPI principal: lleva el Share of Voice.
    som: sov,
    sov,
    sovByBrand,
    brandDetail: detalle,
    mentionShare: error ? null : mentionShare,
    category: (meta && meta.categoria) || f.categoria || '',
    intent: (meta && meta.intencion) || '',
    position: menciona ? f.posicion : null,
    linkPosition: idxPropio >= 0 ? idxPropio + 1 : null,
    mentions: menciona ? (f.n_menciones_bcp || 1) : 0,
    citations: citasPropias,
    sentiment: sentimiento,
    sentimentLabel: etiquetaSentimiento(sentimiento),
    blockAppeared: modelId === 'overview' ? (!error && f.estado !== 'sin_overview') : null,
    brandMentioned: menciona,
    brandCited: !error && f.citado,
    sources,
    sourcesComplete: !trinity,
    searchQueries: leerJson(f.consultas_busqueda, []),
    country: (meta && meta.pais) || 'PE',
    tags: (meta && meta.tags) || [],
    ranking: marcas,
    response: f.respuesta.length > MAX_RESPUESTA ? f.respuesta.slice(0, MAX_RESPUESTA) + '…' : f.respuesta,
    error: f.error,
    isExample: false,
    // Las filas importadas del histórico de Trinity (Pymes) llevan run_id «trinity_…».
    source: trinity ? 'Trinity · histórico importado' : 'n8n · GEO Tracker'
  };
}

// El front muestra como mucho 6 meses; más atrás no se manda.
const DIAS_HISTORIA = 190;
// La respuesta completa queda en el Sheet; al front le basta con esto.
const MAX_RESPUESTA = 4000;

function construirMonitor(filasResultados, filasPrompts, config, hoy, sistema) {
  sistema = sistema || {};
  const desde = new Date(new Date(hoy + 'T12:00:00Z').getTime() - DIAS_HISTORIA * 864e5).toISOString().slice(0, 10);
  const metaPrompts = new Map(filasPrompts.filter(f => f && f.id).map(f => [String(f.id).trim(), normalizarPrompt(f)]));
  // Varias corridas el mismo día: se queda la última de cada prompt y motor.
  const porId = new Map();
  for (const crudo of filasResultados) {
    if (!crudo || !crudo.motor) continue;
    const f = normalizarFila(crudo);
    if (!MODELO_FRONT[f.motor] || !f.prompt_id || !f.fecha || f.fecha < desde) continue;
    const o = observacion(f, config, metaPrompts.get(f.prompt_id));
    const previa = porId.get(o.id);
    if (!previa || String(previa.timestamp) < String(o.timestamp)) porId.set(o.id, o);
  }
  const observations = [...porId.values()].sort((a, b) => a.date.localeCompare(b.date) || a.id.localeCompare(b.id));

  const prompts = filasPrompts.filter(f => f && f.id && String(f.prompt || '').trim()).map(normalizarPrompt);
  // Los proyectos salen de la hoja prompts (activos o con observaciones).
  const conDatos = new Set(observations.map(o => o.promptId));
  const proyectos = new Map();
  for (const p of prompts) {
    if (!p.activo && !conDatos.has(p.id)) continue;
    const id = slug(p.proyecto);
    if (!proyectos.has(id)) proyectos.set(id, { id, name: p.proyecto, promptIds: [], categorias: new Set() });
    const pr = proyectos.get(id);
    pr.promptIds.push(p.id);
    pr.categorias.add(p.categoria);
  }
  // Lo que ya tiene observaciones tiene que existir aunque la hoja prompts haya
  // cambiado (prompt borrado o movido de proyecto): el front busca ambos por id.
  const promptsVistos = new Set(prompts.map(p => p.id));
  const extra = [];
  for (const crudo of filasResultados) {
    if (!crudo || !crudo.motor || !crudo.prompt_id) continue;
    const f = normalizarFila(crudo);
    const id = slug(f.proyecto);
    if (!proyectos.has(id)) proyectos.set(id, { id, name: f.proyecto, promptIds: [], categorias: new Set() });
    const pr = proyectos.get(id);
    if (!pr.promptIds.includes(f.prompt_id)) pr.promptIds.push(f.prompt_id);
    if (crudo.categoria) pr.categorias.add(String(crudo.categoria));
    if (!promptsVistos.has(f.prompt_id)) {
      promptsVistos.add(f.prompt_id);
      extra.push({ id: f.prompt_id, proyecto: f.proyecto, prompt: f.prompt, categoria: String(crudo.categoria || 'Otra'), activo: false });
    }
  }
  prompts.push(...extra);

  const projects = [...proyectos.values()].map(p => ({
    id: p.id,
    name: p.name,
    description: `${p.promptIds.length} prompt${p.promptIds.length === 1 ? '' : 's'} · ${p.categorias.size} categoría${p.categorias.size === 1 ? '' : 's'}`,
    promptIds: p.promptIds,
    example: false
  }));

  const conteo = new Map();
  for (const o of observations) for (const s of o.sources) conteo.set(s.domain, (conteo.get(s.domain) || 0) + 1);
  const domains = [...conteo.entries()].sort((a, b) => b[1] - a[1]).slice(0, 30).map(([d]) => [d, 'https://' + d + '/']);

  // Categoría de cada dominio citado, con las correcciones de la pestaña _dominios.
  const correcciones = {};
  for (const f of sistema._dominios || []) {
    const d = String(f.dominio || '').trim().toLowerCase();
    if (d && CATEGORIAS_DOMINIO.includes(String(f.categoria || '').trim())) correcciones[d] = String(f.categoria).trim();
  }
  const domainCategories = {};
  for (const d of conteo.keys()) domainCategories[d] = categoriaDominio(d, config, correcciones);

  const recStates = {};
  for (const f of sistema._recomendaciones || []) {
    if (f.id) recStates[f.id] = { status: f.estado || 'suggested', owner: f.responsable || '', dueDate: fechaTexto(f.fecha_objetivo), doneAt: fechaTexto(f.fecha_hecha), updatedAt: String(f.actualizado || '') };
  }
  const audits = (sistema._auditorias || []).map(f => ({ id: String(f.id || ''), type: f.tipo, url: f.url, executedAt: String(f.fecha || ''), result: leerJson(f.resultado, null) }))
    .filter(a => a.id && a.result).sort((a, b) => b.executedAt.localeCompare(a.executedAt)).slice(0, 40);

  const marcas = [config.marca].concat(config.competidores || []);
  const brands = marcas.map((m, i) => ({
    id: slug(m.nombre), name: m.nombre, isOwn: i === 0, domains: m.dominios || [], aliases: m.alias || [], color: m.color || '#94a3b8'
  }));
  const aliasPropios = (config.marca.alias || []).map(a => a.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase());
  const esBranded = texto => {
    const t = ' ' + String(texto || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ') + ' ';
    return aliasPropios.some(a => t.includes(' ' + a.replace(/[^a-z0-9]+/g, ' ').trim() + ' '));
  };

  return {
    ok: true,
    generado: new Date().toISOString(),
    monitor: {
      projects,
      observations,
      referenceDate: hoy,
      dates: [...new Set(observations.map(o => o.date))].sort(),
      domains,
      domainCategories,
      brands,
      attributes: config.atributos || [],
      recStates,
      audits
    },
    prompts: prompts.map(p => ({
      id: p.id, text: p.prompt, project: slug(p.proyecto), category: p.categoria, intent: p.intencion, active: p.activo,
      tags: p.tags, funnelStage: p.etapa, intentVolume: p.volumen, country: p.pais, isBranded: esBranded(p.prompt), createdAt: p.fecha_creacion,
      status: 'ok', position: null, linkPosition: null, sov: null, ranking: [],
      response: { isExample: false, screenshotUrl: null, text: '' }
    }))
  };
}

